CREATE OR REPLACE FUNCTION public.create_conversation(p_org_id uuid, p_is_group boolean, p_name text, p_participant_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_creator_id uuid;
  v_conversation_id uuid;
  v_pid uuid;
  v_other_id uuid;
begin
  if not org_feature_enabled(p_org_id, 'messenger') then
    raise exception '메신저 기능이 비활성화된 조직입니다';
  end if;

  select id into v_creator_id from org_members where user_id = auth.uid() and org_id = p_org_id;
  if v_creator_id is null then
    raise exception '해당 조직의 멤버가 아닙니다';
  end if;

  if exists (
    select 1 from unnest(p_participant_ids) pid
    where pid not in (select id from org_members where org_id = p_org_id)
  ) then
    raise exception '참여자 중 같은 조직에 속하지 않은 사용자가 있습니다';
  end if;

  -- 1:1 재사용 시도
  if not p_is_group and array_length(p_participant_ids, 1) = 1 and p_participant_ids[1] <> v_creator_id then
    v_other_id := p_participant_ids[1];
    select c.id into v_conversation_id
    from conversations c
    where c.is_group = false
      and exists (select 1 from conversation_participants where conversation_id = c.id and org_member_id = v_creator_id)
      and exists (select 1 from conversation_participants where conversation_id = c.id and org_member_id = v_other_id)
      and (select count(*) from conversation_participants where conversation_id = c.id) = 2
    limit 1;

    if v_conversation_id is not null then
      update conversation_participants set left_at = null
      where conversation_id = v_conversation_id and org_member_id in (v_creator_id, v_other_id) and left_at is not null;
      return v_conversation_id;
    end if;
  end if;

  insert into conversations (org_id, is_group, name, created_by)
  values (p_org_id, p_is_group, p_name, v_creator_id)
  returning id into v_conversation_id;

  insert into conversation_participants (conversation_id, org_member_id)
  values (v_conversation_id, v_creator_id);

  foreach v_pid in array p_participant_ids loop
    if v_pid <> v_creator_id then
      insert into conversation_participants (conversation_id, org_member_id)
      values (v_conversation_id, v_pid)
      on conflict (conversation_id, org_member_id) do nothing;
    end if;
  end loop;

  return v_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_leave_request(p_org_member_id uuid, p_clinic_id uuid, p_dept_id uuid, p_start_date date, p_end_date date, p_leave_type_id uuid, p_days_count numeric, p_reason text, p_line_template_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_member_name text;
  v_type_name text;
  v_doc_no text;
  v_doc_id uuid;
  v_leave_id uuid;
  v_title text;
  v_content text;
  v_seq int;
begin
  select org_id into v_org_id from org_members where id = p_org_member_id;
  if v_org_id is null then raise exception '조직원을 찾을 수 없습니다.'; end if;
  if not org_feature_enabled(v_org_id, 'approval') then
    raise exception '전자결재 기능이 비활성화된 조직입니다.';
  end if;
  if p_line_template_id is null then raise exception '결재선을 선택해주세요. 소속 부서에 지정된 결재선이 없다면 관리자에게 문의해주세요.'; end if;

  select user_name into v_member_name from org_members_detail where id = p_org_member_id;
  select name into v_type_name from leave_types where id = p_leave_type_id;

  v_seq := next_doc_seq(v_org_id, 'LV', extract(year from current_date)::int);
  v_doc_no := 'LV-' || extract(year from current_date)::int || '-' || lpad(v_seq::text, 6, '0');
  v_title := coalesce(v_type_name, '연차') || ' 신청 (' || p_start_date ||
    (case when p_end_date <> p_start_date then ' ~ ' || p_end_date else '' end) || ')';

  v_content := '<h2 style="text-align:center;">연차 신청서</h2>' ||
    '<table><tbody>' ||
    '<tr><th>신청자</th><td>' || coalesce(v_member_name,'') || '</td><th>유형</th><td>' || coalesce(v_type_name,'') || '</td></tr>' ||
    '<tr><th>기간</th><td>' || p_start_date || (case when p_end_date <> p_start_date then ' ~ ' || p_end_date else '' end) ||
      '</td><th>일수</th><td>' || p_days_count || '일</td></tr>' ||
    '<tr><th>사유</th><td colspan="3">' || coalesce(p_reason,'') || '</td></tr>' ||
    '</tbody></table>';

  insert into leave_requests (org_id, org_member_id, clinic_id, dept_id, start_date, end_date, leave_type_id, days_count, reason, status)
  values (v_org_id, p_org_member_id, p_clinic_id, p_dept_id, p_start_date, p_end_date, p_leave_type_id, p_days_count, p_reason, 'PENDING')
  returning id into v_leave_id;

  insert into approval_documents (org_id, doc_no, doc_type, title, drafter_member_id, clinic_id, dept_id, content_html, status, ref_table, ref_id)
  values (v_org_id, v_doc_no, 'LEAVE', v_title, p_org_member_id, p_clinic_id, p_dept_id, v_content, 'DRAFT', 'leave_requests', v_leave_id)
  returning id into v_doc_id;

  perform apply_approval_line_template(v_doc_id, p_line_template_id);
  perform submit_approval_document(v_doc_id);

  update leave_requests set approval_document_id = v_doc_id where id = v_leave_id;

  return v_leave_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_empty_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.left_at is not null and (old.left_at is null) then
    if not exists (
      select 1 from conversation_participants
      where conversation_id = new.conversation_id and left_at is null
    ) then
      delete from conversations where id = new.conversation_id;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_hr_card_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_exempt text[] := array['hr_memo','self_memo','hr_card_confirmed_at','updated_at','updated_by'];
  v_old_core jsonb;
  v_new_core jsonb;
  k text;
begin
  if OLD.hr_card_confirmed_at is null then
    return NEW;
  end if;

  v_old_core := to_jsonb(OLD);
  v_new_core := to_jsonb(NEW);
  foreach k in array v_exempt loop
    v_old_core := v_old_core - k;
    v_new_core := v_new_core - k;
  end loop;

  if v_old_core = v_new_core then
    return NEW; -- 메모만 수정했거나, 잠금만 해제하는 경우
  end if;

  raise exception '제출 확정된 인사카드 내용은 인사담당자가 잠금을 해제해야 수정할 수 있습니다.';
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_hr_card_lock_related()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_locked boolean;
  v_org_member_id uuid := coalesce(NEW.org_member_id, OLD.org_member_id);
begin
  select (epi.hr_card_confirmed_at is not null)
    into v_locked
  from org_members om
  left join employee_personal_info epi on epi.org_member_id = om.id
  where om.id = v_org_member_id;

  if not coalesce(v_locked, false) then
    return coalesce(NEW, OLD);
  end if;

  raise exception '제출 확정된 인사카드 내용은 인사담당자가 잠금을 해제해야 수정할 수 있습니다.';
end;
$function$

CREATE OR REPLACE FUNCTION public.unlock_hr_card(p_org_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
begin
  select org_id into v_org_id from org_members where id = p_org_member_id;
  if v_org_id is null then raise exception '조직원을 찾을 수 없습니다.'; end if;
  if not (get_org_role(v_org_id) = any (array['admin'::text, 'manager'::text]) or is_platform_admin()) then
    raise exception '인사담당자(manager 이상)만 잠금 해제할 수 있습니다.';
  end if;

  update employee_personal_info set hr_card_confirmed_at = null
  where org_member_id = p_org_member_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.purge_platform_test_data(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dept_id uuid;
  v_dept_code text;
  v_request_ids uuid[];
  v_order_ids uuid[];
  v_receipt_ids uuid[];
  v_item_ids uuid[];
begin
  if not is_platform_admin() then
    raise exception '플랫폼 관리자만 실행할 수 있습니다.';
  end if;

  select id, dept_code into v_dept_id, v_dept_code
  from departments where org_id = p_org_id and is_platform_test = true
  limit 1;

  if v_dept_id is null then
    return jsonb_build_object('message', '정리할 테스트 데이터가 없습니다.');
  end if;

  -- 이 가상 부서가 만든 발주요청 → 거기서 파생된 발주 → 입고(중앙창고) → LOT까지 역추적
  select array_agg(id) into v_request_ids from purchase_requests where dept_id = v_dept_id;
  select array_agg(id) into v_order_ids   from purchase_orders   where request_id = any(v_request_ids);
  select array_agg(id) into v_receipt_ids from stock_receipts    where order_id  = any(v_order_ids);
  select array_agg(distinct item_id) into v_item_ids from stock_receipts where id = any(v_receipt_ids);

  delete from stock_lots where receipt_id = any(v_receipt_ids);
  delete from stock_transactions where ref_type = 'receipt' and ref_id = any(v_receipt_ids);
  delete from stock_receipts where id = any(v_receipt_ids);
  delete from purchase_orders where id = any(v_order_ids);
  delete from purchase_requests where id = any(v_request_ids);

  -- 가상 부서 스코프의 재고 이동/사용/이관 데이터
  delete from stock_transactions where dept_id = v_dept_id;
  delete from stock_dispatch where dept_id = v_dept_id;
  delete from stock_transfers where from_dept_id = v_dept_id or to_dept_id = v_dept_id;
  delete from stock_current where dept_id = v_dept_id;
  delete from stock_lots where dept_id = v_dept_id;

  -- 테스트 입고로 부풀려졌던 중앙창고(dept_id IS NULL) 재고수량을, 실제 남은 거래이력 기준으로 재계산
  if v_item_ids is not null then
    update stock_current sc
    set qty = coalesce((
        select sum(case
          when st.tx_type in ('IN','RETURN') then st.qty
          when st.tx_type = 'OUT' then -abs(st.qty)
          when st.tx_type = 'ADJ' then st.qty
          else 0 end)
        from stock_transactions st
        where st.item_id = sc.item_id and st.dept_id is null
      ), 0),
      last_updated_at = now()
    where sc.item_id = any(v_item_ids) and sc.dept_id is null;
  end if;

  -- 사인물/프로그램 요청 (첨부파일은 CASCADE로 자동 삭제)
  delete from signage_requests where dept_id = v_dept_id;
  delete from program_requests where dept_id = v_dept_id;

  -- 업무일정 (부서는 team_code 텍스트로 매칭)
  delete from task_items where team_code = v_dept_code;

  -- 장비 (하위 이력/점검로그/LJ차트/알림로그는 전부 CASCADE)
  delete from equipments where team_code = v_dept_code;

  -- 가상 부서 자체는 삭제하지 않고 그대로 유지 (재사용) — 데이터만 정리
  return jsonb_build_object('message', '테스트 데이터를 정리했습니다.');
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_approval_document(p_doc_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_doc record;
  v_step record;
  v_only_approver record;
  v_approver_count int;
begin
  select * into v_doc from approval_documents where id = p_doc_id for update;
  if v_doc is null then raise exception '문서를 찾을 수 없습니다.'; end if;
  if v_doc.status <> 'DRAFT' then raise exception 'DRAFT 상태의 문서만 상신할 수 있습니다.'; end if;
  if not (v_doc.drafter_member_id in (select id from org_members where org_id = v_doc.org_id and user_id = auth.uid())) then
    raise exception '기안자 본인만 상신할 수 있습니다.';
  end if;
  if not exists (select 1 from approval_steps where document_id = p_doc_id) then
    raise exception '결재선이 지정되지 않았습니다.';
  end if;

  -- 맨 앞의 미완료(SKIPPED 아닌) 스텝을 찾아 활성화
  select * into v_step from approval_steps
    where document_id = p_doc_id and status = 'PENDING'
    order by step_no asc limit 1;

  if v_step is null then
    -- 모든 스텝이 SKIPPED인 경우 (결재자 전혀 없음) → 바로 승인 처리
    update approval_documents set status = 'APPROVED', submitted_at = now(), completed_at = now(), current_step_no = 0, updated_at = now()
      where id = p_doc_id;
    return;
  end if;

  update approval_steps set status = 'IN_PROGRESS', started_at = now() where id = v_step.id;
  update approval_documents set status = 'IN_PROGRESS', submitted_at = now(), current_step_no = v_step.step_no, updated_at = now()
    where id = p_doc_id;

  -- 맨 첫 단계에 한해서만: 그 유일한 결재자가 기안자 본인이면, 본인이 본인 문서를 결재하는
  -- 불필요한 절차를 만들지 않기 위해 자동으로 승인 처리하고 다음 단계로 넘긴다.
  -- (한 단계에 결재자가 2명 이상이면 자동승인하지 않는다.)
  -- 주의: 여기서 더 이상 반복(loop)하지 않는다 — 2단계 이후는 결재자가 기안자와 같은 사람이더라도
  -- 서로 다른 결재 단계이므로, 반드시 결재함에서 실제 승인 행위를 거치도록 한다.
  select count(*) into v_approver_count from approval_step_approvers where step_id = v_step.id;
  if v_approver_count = 1 and v_step.step_type = 'APPROVE' then
    select * into v_only_approver from approval_step_approvers where step_id = v_step.id limit 1;
    if v_only_approver.org_member_id = v_doc.drafter_member_id then
      update approval_step_approvers set action = 'APPROVED', acted_at = now() where id = v_only_approver.id;
      update approval_steps set status = 'APPROVED', completed_at = now() where id = v_step.id;

      select * into v_step from approval_steps
        where document_id = p_doc_id and status = 'PENDING' and step_no > v_step.step_no
        order by step_no asc limit 1;

      if v_step is null then
        update approval_documents set status = 'APPROVED', completed_at = now(), updated_at = now() where id = p_doc_id;
        return;
      end if;

      update approval_steps set status = 'IN_PROGRESS', started_at = now() where id = v_step.id;
      update approval_documents set current_step_no = v_step.step_no, updated_at = now() where id = p_doc_id;
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.act_on_approval_step(p_step_approver_id uuid, p_action text, p_comment text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sa record;
  v_step record;
  v_doc record;
  v_pending_count int;
  v_next_step record;
begin
  if p_action not in ('APPROVED','REJECTED') then
    raise exception '잘못된 액션입니다.';
  end if;

  select sa.*, s.document_id, s.decision_rule, s.step_type, s.status as step_status, s.step_no
    into v_sa
    from approval_step_approvers sa
    join approval_steps s on s.id = sa.step_id
    where sa.id = p_step_approver_id
    for update of sa;
  if v_sa is null then raise exception '결재 항목을 찾을 수 없습니다.'; end if;

  select * into v_doc from approval_documents where id = v_sa.document_id for update;

  if not exists (select 1 from org_members where id = v_sa.org_member_id and user_id = auth.uid()) then
    raise exception '본인의 결재 항목만 처리할 수 있습니다.';
  end if;
  if v_sa.step_status <> 'IN_PROGRESS' then
    raise exception '현재 진행 중인 스텝이 아닙니다.';
  end if;
  if v_sa.action <> 'PENDING' then
    raise exception '이미 처리된 항목입니다.';
  end if;

  update approval_step_approvers set action = p_action, comment = coalesce(p_comment,''), acted_at = now()
    where id = p_step_approver_id;

  select * into v_step from approval_steps where id = v_sa.step_id for update;

  -- 결재(APPROVE) 단계의 반려만 문서 전체를 반려시킨다. 협의(CONSULT) 단계의 반려는
  -- "반대 의견"으로 기록될 뿐 진행을 막지 않는다 — 아래로 흘러가 그냥 의견 제출 완료 처리된다.
  if p_action = 'REJECTED' and v_step.step_type = 'APPROVE' then
    update approval_steps set status = 'REJECTED', completed_at = now() where id = v_step.id;
    update approval_step_approvers set action = 'SKIPPED' where step_id = v_step.id and action = 'PENDING';
    update approval_steps set status = 'SKIPPED' where document_id = v_step.document_id and status = 'PENDING';
    update approval_documents set status = 'REJECTED', completed_at = now(), updated_at = now() where id = v_step.document_id;
    return;
  end if;

  if v_step.decision_rule = 'ANY' then
    update approval_step_approvers set action = 'SKIPPED' where step_id = v_step.id and action = 'PENDING';
    update approval_steps set status = 'APPROVED', completed_at = now() where id = v_step.id;
  else -- ALL
    select count(*) filter (where action = 'PENDING') into v_pending_count from approval_step_approvers where step_id = v_step.id;
    if v_pending_count = 0 then
      update approval_steps set status = 'APPROVED', completed_at = now() where id = v_step.id;
    end if;
  end if;

  if (select status from approval_steps where id = v_step.id) = 'APPROVED' then
    select * into v_next_step from approval_steps
      where document_id = v_step.document_id and status = 'PENDING' and step_no > v_step.step_no
      order by step_no asc limit 1;
    if v_next_step is null then
      update approval_documents set status = 'APPROVED', completed_at = now(), updated_at = now() where id = v_step.document_id;
    else
      update approval_steps set status = 'IN_PROGRESS', started_at = now() where id = v_next_step.id;
      update approval_documents set current_step_no = v_next_step.step_no, updated_at = now() where id = v_step.document_id;
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_leave_request(p_org_member_id uuid, p_clinic_id uuid, p_dept_id uuid, p_start_date date, p_end_date date, p_leave_type_id uuid, p_days_count numeric, p_reason text, p_line_template_id uuid DEFAULT NULL::uuid, p_manual_steps jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
  v_member_name text;
  v_type_name text;
  v_doc_no text;
  v_doc_id uuid;
  v_leave_id uuid;
  v_title text;
  v_content text;
  v_seq int;
  v_step jsonb;
  v_step_no int;
  v_step_id uuid;
  v_approver_id text;
begin
  select org_id into v_org_id from org_members where id = p_org_member_id;
  if v_org_id is null then raise exception '조직원을 찾을 수 없습니다.'; end if;
  if not org_feature_enabled(v_org_id, 'approval') then
    raise exception '전자결재 기능이 비활성화된 조직입니다.';
  end if;
  if p_line_template_id is null and (p_manual_steps is null or jsonb_array_length(p_manual_steps) = 0) then
    raise exception '결재선을 선택하거나 직접 지정해주세요.';
  end if;

  select user_name into v_member_name from org_members_detail where id = p_org_member_id;
  select name into v_type_name from leave_types where id = p_leave_type_id;

  v_seq := next_doc_seq(v_org_id, 'LV', extract(year from current_date)::int);
  v_doc_no := 'LV-' || extract(year from current_date)::int || '-' || lpad(v_seq::text, 6, '0');
  v_title := coalesce(v_type_name, '연차') || ' 신청 (' || p_start_date ||
    (case when p_end_date <> p_start_date then ' ~ ' || p_end_date else '' end) || ')';

  v_content := '<h2 style="text-align:center;">연차 신청서</h2>' ||
    '<table><tbody>' ||
    '<tr><th>신청자</th><td>' || coalesce(v_member_name,'') || '</td><th>유형</th><td>' || coalesce(v_type_name,'') || '</td></tr>' ||
    '<tr><th>기간</th><td>' || p_start_date || (case when p_end_date <> p_start_date then ' ~ ' || p_end_date else '' end) ||
      '</td><th>일수</th><td>' || p_days_count || '일</td></tr>' ||
    '<tr><th>사유</th><td colspan="3">' || coalesce(p_reason,'') || '</td></tr>' ||
    '</tbody></table>';

  insert into leave_requests (org_id, org_member_id, clinic_id, dept_id, start_date, end_date, leave_type_id, days_count, reason, status)
  values (v_org_id, p_org_member_id, p_clinic_id, p_dept_id, p_start_date, p_end_date, p_leave_type_id, p_days_count, p_reason, 'PENDING')
  returning id into v_leave_id;

  insert into approval_documents (org_id, doc_no, doc_type, title, drafter_member_id, clinic_id, dept_id, content_html, status, ref_table, ref_id)
  values (v_org_id, v_doc_no, 'LEAVE', v_title, p_org_member_id, p_clinic_id, p_dept_id, v_content, 'DRAFT', 'leave_requests', v_leave_id)
  returning id into v_doc_id;

  if p_line_template_id is not null then
    perform apply_approval_line_template(v_doc_id, p_line_template_id);
  else
    v_step_no := 0;
    for v_step in select * from jsonb_array_elements(p_manual_steps)
    loop
      v_step_no := v_step_no + 1;
      insert into approval_steps (document_id, step_no, decision_rule, step_type, status)
      values (v_doc_id, v_step_no, coalesce(v_step->>'decision_rule','ALL'), coalesce(v_step->>'step_type','APPROVE'), 'PENDING')
      returning id into v_step_id;

      for v_approver_id in select jsonb_array_elements_text(v_step->'approver_ids')
      loop
        insert into approval_step_approvers (step_id, org_member_id) values (v_step_id, v_approver_id::uuid);
      end loop;

      if not exists (select 1 from approval_step_approvers where step_id = v_step_id) then
        update approval_steps set status = 'SKIPPED' where id = v_step_id;
      end if;
    end loop;
  end if;

  perform submit_approval_document(v_doc_id);

  update leave_requests set approval_document_id = v_doc_id where id = v_leave_id;

  return v_leave_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_org_admin_account(p_org_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member_id uuid;
  v_clinic_id uuid;
  v_dept_id uuid;
  v_new_user_id uuid;
  v_dept_code text;
begin
  if not is_platform_admin() then
    raise exception '플랫폼 관리자만 실행할 수 있습니다.';
  end if;

  select id into v_member_id from org_members
  where org_id = p_org_id and is_platform_system_account = true limit 1;
  if v_member_id is not null then
    return v_member_id;
  end if;

  select id into v_clinic_id from clinics where org_id = p_org_id order by created_at limit 1;
  if v_clinic_id is null then
    raise exception '의원이 없어서 미리보기용 계정을 만들 수 없습니다.';
  end if;

  select id into v_dept_id from departments where org_id = p_org_id and is_platform_test = true and clinic_id = v_clinic_id limit 1;
  if v_dept_id is null then
    select generate_dept_code(p_org_id) into v_dept_code;
    insert into departments (org_id, clinic_id, dept_code, dept_name, team_group_code, sort_order, active, is_platform_test)
    values (p_org_id, v_clinic_id, v_dept_code, '🧪 플랫폼 테스트용 (숨김)', '', 999, 'N', true)
    returning id into v_dept_id;
  end if;

  v_new_user_id := gen_random_uuid();
  insert into auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    banned_until, is_sso_user, is_anonymous, created_at, updated_at
  ) values (
    v_new_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
    'system-admin+' || p_org_id || '@internal.maneasy.local',
    extensions.crypt(gen_random_uuid()::text, extensions.gen_salt('bf')),
    now(), '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('user_name', '플랫폼 미리보기 계정'),
    '2999-12-31'::timestamptz, false, false, now(), now()
