CREATE OR REPLACE FUNCTION public.get_leave_balance(p_org_member_id uuid, p_as_of_date date DEFAULT CURRENT_DATE)
 RETURNS TABLE(period_start date, period_end date, basis text, years_of_service integer, entitlement_days numeric, carried_over_days numeric, used_days numeric, adjustment_days numeric, remaining_days numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member org_members;
  v_policy leave_policies;
  v_hire date;
  v_p_start date;
  v_p_end date;
  v_years int;
  v_entitlement numeric;
  v_used numeric;
  v_adj numeric;
  v_carry_in numeric := 0;
  v_remaining numeric;
  v_is_current boolean;
  v_guard int := 0;
begin
  select * into v_member from org_members where id = p_org_member_id;
  if v_member.id is null then
    raise exception '조직원을 찾을 수 없습니다: %', p_org_member_id;
  end if;

  if not (
    exists (select 1 from org_members om where om.id = p_org_member_id and om.user_id = auth.uid())
    or get_org_role(v_member.org_id) = any (array['admin'::text, 'manager'::text])
    or is_platform_admin()
  ) then
    raise exception '본인 또는 관리자만 조회할 수 있습니다.';
  end if;

  select * into v_policy from get_leave_policy(v_member.org_id, v_member.clinic_id);
  if v_policy.id is null then
    raise exception '적용할 연차 정책이 없습니다(org_id=%, clinic_id=%). 정책을 먼저 등록해주세요.', v_member.org_id, v_member.clinic_id;
  end if;

  -- 연차 계산 기산일은 입사일과 별도로 지정할 수 있다(leave_start_date). 지정 안 했으면
  -- 예전처럼 입사일을 그대로 쓴다(하위호환).
  v_hire := coalesce(v_member.leave_start_date, v_member.hire_date);
  if v_hire is null then
    raise exception '해당 조직원의 입사일(또는 연차 기산일)이 등록되어 있지 않습니다.';
  end if;
  if v_hire > p_as_of_date then
    raise exception '기준일이 연차 기산일보다 이전입니다.';
  end if;

  v_p_start := v_hire;

  loop
    v_guard := v_guard + 1;
    if v_guard > 100 then
      raise exception '연차 기간 계산이 비정상적으로 길어졌습니다(100회 초과) — 정책/기산일을 확인해주세요.';
    end if;

    if v_policy.basis = 'HIRE_DATE' then
      v_p_end := v_p_start + interval '1 year' - interval '1 day';
      v_years := extract(year from age(v_p_start, v_hire))::int;
    else
      v_p_end := make_date(extract(year from v_p_start)::int, 12, 31);
      v_years := extract(year from age(v_p_start, v_hire))::int;
    end if;

    v_is_current := p_as_of_date <= v_p_end;

    if v_years < 1 then
      v_entitlement := least(v_policy.first_year_max_days,
        months_completed(v_hire, least(p_as_of_date, v_p_end)) * v_policy.first_year_monthly_days);
    else
      v_entitlement := calc_leave_days_by_years(v_policy, v_years);
    end if;

    select coalesce(sum(r.days_count), 0) into v_used
    from leave_requests r
    where r.org_member_id = p_org_member_id and r.status = 'APPROVED'
      and r.start_date <= v_p_end and r.end_date >= v_p_start;

    select coalesce(sum(a.adjustment_days), 0) into v_adj
    from leave_adjustments a
    where a.org_member_id = p_org_member_id
      and a.period_start = v_p_start and a.period_end = v_p_end;

    v_remaining := v_entitlement + v_carry_in + v_adj - v_used;

    if v_is_current then
      return query select v_p_start, v_p_end, v_policy.basis, v_years,
        v_entitlement, v_carry_in, v_used, v_adj, v_remaining;
      return;
    end if;

    v_carry_in := apply_carryover_policy(v_policy, v_remaining);
    v_p_start := v_p_end + interval '1 day';
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public._rollback_session_rows(p_session_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_count int := 0;
begin
  for r in
    select * from admin_audit_log
    where impersonation_session_id = p_session_id
      and rolled_back_at is null
    order by created_at desc
  loop
    if r.action = 'INSERT' then
      execute format('delete from %I where id = %L', r.table_name, r.record_id);
    elsif r.action = 'UPDATE' then
      execute format(
        'update %I set %s where id = %L',
        r.table_name,
        (select string_agg(format('%I = %L', kv.key, kv.value), ', ')
           from jsonb_each_text(r.before_data) as kv(key, value)
           where kv.key <> 'id'),
        r.record_id
      );
    elsif r.action = 'DELETE' then
      execute format(
        'insert into %I select * from jsonb_populate_record(null::%I, %L)',
        r.table_name, r.table_name, r.before_data
      );
    end if;

    update admin_audit_log set rolled_back_at = now() where id = r.id;
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_approval_line_template(p_doc_id uuid, p_template_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_doc record;
  v_step record;
  v_approver record;
  v_resolved_member uuid;
begin
  select * into v_doc from approval_documents where id = p_doc_id;
  if v_doc is null then raise exception '문서를 찾을 수 없습니다.'; end if;
  if v_doc.status <> 'DRAFT' then raise exception 'DRAFT 상태의 문서만 결재선을 적용할 수 있습니다.'; end if;
  if not (v_doc.drafter_member_id in (select id from org_members where org_id = v_doc.org_id and user_id = auth.uid())
          or get_org_role(v_doc.org_id) = 'admin' or is_platform_admin()) then
    raise exception '권한이 없습니다.';
  end if;

  delete from approval_steps where document_id = p_doc_id;

  for v_step in
    select * from approval_line_template_steps where template_id = p_template_id order by step_no
  loop
    insert into approval_steps (document_id, step_no, decision_rule, step_type, status)
    values (p_doc_id, v_step.step_no, v_step.decision_rule, v_step.step_type, 'PENDING')
    returning id into v_step.id;

    for v_approver in
      select * from approval_line_template_approvers where template_step_id = (
        select id from approval_line_template_steps where template_id = p_template_id and step_no = v_step.step_no
      )
    loop
      if v_approver.approver_type = 'MEMBER' then
        insert into approval_step_approvers (step_id, org_member_id) values (v_step.id, v_approver.org_member_id);
      elsif v_approver.role_code = 'DRAFTER' then
        -- 기안자 본인 — 문서마다 다시 해석되므로 템플릿 하나로 모든 기안자에게 통용됨
        insert into approval_step_approvers (step_id, org_member_id) values (v_step.id, v_doc.drafter_member_id);
      elsif v_approver.role_code = 'DEPT_MANAGER' then
        select manager_id into v_resolved_member from departments where id = v_doc.dept_id;
        if v_resolved_member is not null then
          insert into approval_step_approvers (step_id, org_member_id) values (v_step.id, v_resolved_member);
        end if;
      end if;
    end loop;

    if not exists (select 1 from approval_step_approvers where step_id = v_step.id) then
      update approval_steps set status = 'SKIPPED' where id = v_step.id;
    end if;
  end loop;

  update approval_documents set line_template_id = p_template_id, updated_at = now() where id = p_doc_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.retract_approval_step(p_step_approver_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sa record;
  v_step record;
  v_doc record;
  v_later_acted boolean;
begin
  select sa.*, s.document_id, s.step_no
    into v_sa
    from approval_step_approvers sa
    join approval_steps s on s.id = sa.step_id
    where sa.id = p_step_approver_id
    for update of sa;
  if v_sa is null then raise exception '결재 항목을 찾을 수 없습니다.'; end if;

  if not exists (select 1 from org_members where id = v_sa.org_member_id and user_id = auth.uid()) then
    raise exception '본인의 결재만 취소할 수 있습니다.';
  end if;
  if v_sa.action = 'PENDING' then
    raise exception '아직 처리하지 않은 항목입니다.';
  end if;
  if v_sa.action = 'SKIPPED' then
    raise exception '건너뛴 항목은 취소할 수 없습니다.';
  end if;

  select * into v_step from approval_steps where id = v_sa.step_id for update;
  select * into v_doc from approval_documents where id = v_step.document_id for update;

  if v_doc.status = 'REJECTED' then
    raise exception '반려로 종료된 문서는 결재를 취소할 수 없습니다.';
  end if;
  if v_doc.status = 'CANCELED' then
    raise exception '취소된 문서입니다.';
  end if;

  -- 이 단계 이후에 실제로 사람이 승인/반려한 이력이 있으면, 절차가 이미 더 진행된 것이므로
  -- 안전하게 되돌릴 수 없다(뒷사람이 이미 내 결재를 전제로 판단을 내린 상태이기 때문).
  select exists (
    select 1 from approval_steps s2
    join approval_step_approvers sa2 on sa2.step_id = s2.id
    where s2.document_id = v_step.document_id and s2.step_no > v_step.step_no and sa2.action in ('APPROVED','REJECTED')
  ) into v_later_acted;
  if v_later_acted then
    raise exception '이후 단계에서 이미 결재가 진행되어 취소할 수 없습니다.';
  end if;

  -- 이 스텝 자체를 되돌린다(같은 스텝 안에서 ANY 룰 때문에 SKIPPED됐던 다른 결재자들도 함께 되돌림)
  update approval_step_approvers set action = 'PENDING', acted_at = null, comment = '' where id = p_step_approver_id;
  update approval_step_approvers set action = 'PENDING', acted_at = null where step_id = v_step.id and action = 'SKIPPED';
  update approval_steps set status = 'IN_PROGRESS', completed_at = null where id = v_step.id;

  -- 다음 단계들이 이미 시작(IN_PROGRESS)돼 있었지만 아무도 손대지 않았다면 함께 되돌린다.
  update approval_steps set status = 'PENDING', started_at = null
    where document_id = v_step.document_id and step_no > v_step.step_no and status in ('IN_PROGRESS','APPROVED');
  update approval_step_approvers set action = 'PENDING', acted_at = null
    where step_id in (select id from approval_steps where document_id = v_step.document_id and step_no > v_step.step_no);

  update approval_documents set status = 'IN_PROGRESS', current_step_no = v_step.step_no, completed_at = null, updated_at = now()
    where id = v_step.document_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_family_resident_number(p_family_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_row record;
  v_key text;
begin
  select f.id, f.resident_number_enc, om.org_id
    into v_row
    from employee_family_members f
    join org_members om on om.id = f.org_member_id
    where f.id = p_family_id;

  if v_row.id is null then
    raise exception '가족 정보를 찾을 수 없습니다.';
  end if;

  if not (get_org_role(v_row.org_id) = any (array['admin'::text, 'manager'::text]) or is_platform_admin()) then
    raise exception '관리자만 주민번호 확인이 가능합니다.';
  end if;

  if v_row.resident_number_enc is null then
    return null;
  end if;

  select value into v_key from app_secrets where key = 'resident_number_key';
  return pgp_sym_decrypt(v_row.resident_number_enc, v_key);
end;
$function$

