    select coalesce(sum(a.adjustment_days), 0) into v_adj
    from leave_adjustments a
    where a.org_member_id = p_org_member_id
      and a.period_start = v_p_start and a.period_end = v_p_end;

    v_remaining := v_entitlement + v_carry_in + v_adj - v_used;
    v_carry_out := apply_carryover_policy(v_policy, v_remaining);

    return query select v_p_start, v_p_end, v_years, v_entitlement, v_carry_in, v_used, v_adj, v_remaining,
      v_carry_out, greatest(v_remaining - v_carry_out, 0), v_is_current;

    if v_is_current then
      return;
    end if;

    v_carry_in := v_carry_out;
    v_p_start := v_p_end + interval '1 day';
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.encrypt_resident_number_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_key text;
begin
  if NEW.resident_number_plain is not null and length(trim(NEW.resident_number_plain)) > 0 then
    select value into v_key from app_secrets where key = 'resident_number_key';
    NEW.resident_number_enc := pgp_sym_encrypt(NEW.resident_number_plain, v_key);
  elsif TG_OP = 'INSERT' and NEW.resident_number_enc is null then
    NEW.resident_number_enc := null;
  end if;
  NEW.resident_number_plain := null;
  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.auto_renew_and_expire_contracts()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_months int;
  v_new_start date;
  v_new_end date;
begin
  -- 자동연장: 기간형 + auto_renew='Y' + 계약종료일이 지났으면, 종료일 기준으로 주기(개월)만큼
  -- 밀어서 다음 계약기간으로 굴린다. 여러 주기가 밀려있었을 경우(cron이 며칠 못 돌았던 경우 등)
  -- 오늘 날짜를 포함하는 주기까지 한 번에 따라잡는다.
  for r in
    select id, contract_start, contract_end, auto_renew_cycle_months
    from contracts
    where status = 'ACTIVE' and has_period = 'Y' and auto_renew = 'Y'
      and contract_end is not null and contract_end < current_date
      and deleted_at is null
  loop
    v_months := coalesce(r.auto_renew_cycle_months, 12);
    v_new_start := r.contract_start;
    v_new_end := r.contract_end;
    while v_new_end < current_date loop
      v_new_start := v_new_start + (v_months || ' months')::interval;
      v_new_end := v_new_end + (v_months || ' months')::interval;
    end loop;
    update contracts set contract_start = v_new_start, contract_end = v_new_end, updated_at = now()
    where id = r.id;
  end loop;

  -- 자동만료: 계약종료일이 지났고(또는 단건형 계약일이 지났고), 유지(하자)보수기간까지 잡혀있다면
  -- 그 기간도 지나야 진짜 만료 처리한다. 자동연장 계약은 위에서 이미 갱신되어 여기 안 걸린다.
  update contracts
  set status = 'EXPIRED', updated_at = now()
  where status = 'ACTIVE'
    and deleted_at is null
    and (
      (has_period = 'Y' and contract_end is not null and contract_end < current_date and coalesce(auto_renew, 'N') = 'N')
      or
      (has_period = 'N' and contract_start is not null and contract_start < current_date)
    )
    and not (has_warranty and warranty_end is not null and warranty_end >= current_date);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_member_hr_dates(p_org_member_id uuid, p_hire_date date, p_resign_date date, p_leave_start_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org_id uuid;
begin
  select org_id into v_org_id from org_members where id = p_org_member_id;
  if v_org_id is null then
    raise exception '조직원을 찾을 수 없습니다: %', p_org_member_id;
  end if;

  if not (get_org_role(v_org_id) = any (array['admin'::text, 'manager'::text]) or is_platform_admin()) then
    raise exception '관리자만 수정할 수 있습니다.';
  end if;

  update org_members
  set hire_date = p_hire_date,
      resign_date = p_resign_date,
      leave_start_date = p_leave_start_date,
      -- 퇴사일을 입력하면 자동으로 비활성 처리(로그인 차단). 지운다고 자동으로
      -- 다시 활성화되지는 않는다(재활성화는 사용자관리에서 명시적으로 하도록).
      active = case when p_resign_date is not null then false else active end
  where id = p_org_member_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_hr_card(p_org_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner_uid uuid;
begin
  select user_id into v_owner_uid from org_members where id = p_org_member_id;
  if v_owner_uid is null then raise exception '조직원을 찾을 수 없습니다.'; end if;
  if auth.uid() != v_owner_uid then raise exception '본인만 제출 확정할 수 있습니다.'; end if;

  update employee_personal_info set hr_card_confirmed_at = now()
  where org_member_id = p_org_member_id;
  if not found then
    insert into employee_personal_info (org_id, org_member_id, hr_card_confirmed_at)
    select org_id, p_org_member_id, now() from org_members where id = p_org_member_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.log_admin_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  active_session_id uuid;
  rec_org_id uuid;
begin
  rec_org_id := coalesce(new.org_id, old.org_id);

  select id into active_session_id
  from admin_impersonation_sessions
  where admin_user_id = auth.uid()
    and org_id = rec_org_id
    and expires_at > now()
    and ended_at is null
  limit 1;

  if active_session_id is not null then
    insert into admin_audit_log (
      impersonation_session_id, admin_user_id, org_id,
      table_name, action, record_id, before_data, after_data
    ) values (
      active_session_id, auth.uid(), rec_org_id,
      TG_TABLE_NAME, TG_OP,
      coalesce(new.id::text, old.id::text),
      case when TG_OP != 'INSERT' then to_jsonb(old) else null end,
      case when TG_OP != 'DELETE' then to_jsonb(new) else null end
    );
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_invite_code(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invite record;
begin
  select * into v_invite from org_invite_codes
    where code = p_code and active = true
    for update;

  if not found then
    return jsonb_build_object('success', false, 'error', '유효하지 않은 초대코드입니다.');
  end if;
  if v_invite.expires_at is not null and v_invite.expires_at < now() then
    return jsonb_build_object('success', false, 'error', '만료된 초대코드입니다.');
  end if;
  if v_invite.used_count >= v_invite.max_uses then
    return jsonb_build_object('success', false, 'error', '사용 횟수를 초과한 초대코드입니다.');
  end if;
  if exists (select 1 from org_members where org_id = v_invite.org_id and user_id = auth.uid()) then
    return jsonb_build_object('success', false, 'error', '이미 해당 조직에 소속되어 있습니다.');
  end if;

  insert into org_members (org_id, user_id, role, clinic_id)
    values (v_invite.org_id, auth.uid(), v_invite.role, v_invite.clinic_id);
  update org_invite_codes set used_count = used_count + 1 where id = v_invite.id;

  return jsonb_build_object('success', true, 'org_id', v_invite.org_id, 'role', v_invite.role);
end;
$function$

CREATE OR REPLACE FUNCTION public.rollback_impersonation_session(p_session_id uuid)
 RETURNS TABLE(reverted_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int;
begin
  if not is_platform_admin() then
    raise exception '플랫폼 관리자만 사용할 수 있습니다.';
  end if;
  if not exists (
    select 1 from admin_impersonation_sessions
    where id = p_session_id and admin_user_id = auth.uid()
  ) then
    raise exception '본인이 시작한 세션만 되돌릴 수 있습니다.';
  end if;

  v_count := _rollback_session_rows(p_session_id);

  update admin_impersonation_sessions
  set ended_at = coalesce(ended_at, now())
  where id = p_session_id;

  return query select v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_impersonation(target_org_id uuid, impersonation_reason text)
 RETURNS TABLE(session_id uuid, expires_at timestamp with time zone, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  new_session_id uuid;
  v_expires timestamptz;
  existing record;
begin
  if not is_platform_admin() then
    raise exception '플랫폼 관리자만 사용할 수 있습니다.';
  end if;
  if impersonation_reason is null or length(trim(impersonation_reason)) = 0 then
    raise exception '사유를 입력해야 합니다.';
  end if;

  select s.id, s.expires_at, s.reason into existing
  from admin_impersonation_sessions s
  where s.admin_user_id = auth.uid()
    and s.org_id = target_org_id
    and s.expires_at > now()
    and s.ended_at is null
  order by s.started_at desc
  limit 1;

  if existing.id is not null then
    return query select existing.id, existing.expires_at, existing.reason;
    return;
  end if;

  insert into admin_impersonation_sessions (admin_user_id, org_id, reason)
  values (auth.uid(), target_org_id, impersonation_reason)
  returning id, admin_impersonation_sessions.expires_at into new_session_id, v_expires;

  return query select new_session_id, v_expires, impersonation_reason;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_add_existing_member(p_org_id uuid, p_email text, p_role text, p_clinic_id uuid, p_dept_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_existing_id uuid;
  v_new_id uuid;
  v_user_name text;
begin
  if not is_platform_admin() then
    raise exception '플랫폼 관리자만 사용할 수 있습니다.';
  end if;

  select id into v_user_id from auth.users
  where lower(email) = lower(trim(p_email)) and email not ilike '%@internal.maneasy.local'
  limit 1;

  if v_user_id is null then
    return jsonb_build_object('success', false, 'error', '해당 이메일로 가입된 사용자를 찾을 수 없습니다.');
  end if;

  select id into v_existing_id from org_members where org_id = p_org_id and user_id = v_user_id;
  if v_existing_id is not null then
    return jsonb_build_object('success', false, 'error', '이미 해당 의원에 소속되어 있습니다.');
  end if;

  insert into org_members (org_id, user_id, role, clinic_id, dept_id, active)
  values (p_org_id, v_user_id, p_role, p_clinic_id, p_dept_id, true)
  returning id into v_new_id;

  select user_name into v_user_name from profiles where id = v_user_id;

  return jsonb_build_object('success', true, 'org_member_id', v_new_id, 'user_name', coalesce(v_user_name, p_email));
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_dept_name_to_contracts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.dept_name is distinct from old.dept_name then
    update contracts set dept_name = new.dept_name, updated_at = now() where dept_id = new.id;
  end if;
  return new;
end;
$function$
